package netsec

import (
	"bytes"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strings"
)

// QRParty is one account binding carried by a QR payload.
type QRParty struct {
	AccountID   string
	ListVersion uint64
	ListDigest  [32]byte

	// AccountDigest is optional on import for interoperability, but payloads
	// generated by this package always include it. Verification always
	// recomputes it from the verifier's current snapshot.
	AccountDigest [32]byte
}

// QRPayload is the canonical two-party safety-number QR payload.
type QRPayload struct {
	ProtocolVersion uint16
	Accounts        []QRParty
	Checksum        [32]byte
}

type qrPayloadJSON struct {
	ProtocolVersion uint16        `json:"protocol_version"`
	Accounts        []qrPartyJSON `json:"accounts"`
	Checksum        string        `json:"checksum"`
}

type qrPartyJSON struct {
	AccountID     string `json:"account_id"`
	ListVersion   uint64 `json:"list_version"`
	ListDigest    string `json:"list_digest"`
	AccountDigest string `json:"account_digest,omitempty"`
}

// NewQRPayload builds a payload from two complete snapshots. Account entries
// are sorted by account ID so independent clients generate byte-identical
// payloads.
func NewQRPayload(a, b *DeviceListSnapshot) (*QRPayload, error) {
	left, err := EnsureValid(a)
	if err != nil {
		return nil, err
	}
	right, err := EnsureValid(b)
	if err != nil {
		return nil, err
	}
	if left.AccountID == right.AccountID {
		return nil, ErrDuplicateAccount
	}
	first := QRPartyFromSnapshot(left)
	second := QRPartyFromSnapshot(right)
	if first.AccountID > second.AccountID {
		first, second = second, first
	}
	return NewQRPayloadFromParts(first, second), nil
}

// NewQRPayloadFromParts constructs and validates a payload from two account
// bindings. The passed order is preserved, but the checksum is order
// independent.
func NewQRPayloadFromParts(first, second QRParty) *QRPayload {
	return &QRPayload{
		ProtocolVersion: ProtocolVersion,
		Accounts:        []QRParty{first, second},
		Checksum:        PairwiseChecksum(first.AccountDigest, second.AccountDigest),
	}
}

// QRPartyFromSnapshot projects the security-relevant fields of a snapshot.
func QRPartyFromSnapshot(snapshot *DeviceListSnapshot) QRParty {
	if snapshot == nil {
		return QRParty{}
	}
	return QRParty{
		AccountID:     snapshot.AccountID,
		ListVersion:   snapshot.Version,
		ListDigest:    snapshot.ListDigest,
		AccountDigest: snapshot.AccountDigest,
	}
}

// SafetyNumber returns the safety number represented by the payload. It
// requires both AccountDigest fields; a minimal payload carrying only list
// digests must be verified against local snapshots first.
func (p *QRPayload) SafetyNumber() (*SafetyNumber, error) {
	if err := p.Validate(); err != nil {
		return nil, err
	}
	if isZeroDigest(p.Accounts[0].AccountDigest) || isZeroDigest(p.Accounts[1].AccountDigest) {
		return nil, fmt.Errorf("%w: account identity digests omitted", ErrInvalidQRPayload)
	}
	return SafetyNumberFromAccountDigests(p.Accounts[0].AccountDigest, p.Accounts[1].AccountDigest), nil
}

// SortedAccounts returns a stable copy sorted by account ID.
func (p *QRPayload) SortedAccounts() []QRParty {
	if p == nil {
		return nil
	}
	accounts := append([]QRParty(nil), p.Accounts...)
	sort.Slice(accounts, func(i, j int) bool {
		return accounts[i].AccountID < accounts[j].AccountID
	})
	return accounts
}

// WithSwappedAccounts returns a copy with the two account entries reversed.
// The checksum remains valid because digest ordering is bytewise.
func (p *QRPayload) WithSwappedAccounts() *QRPayload {
	if p == nil {
		return nil
	}
	clone := *p
	clone.Accounts = append([]QRParty(nil), p.Accounts...)
	if len(clone.Accounts) == 2 {
		clone.Accounts[0], clone.Accounts[1] = clone.Accounts[1], clone.Accounts[0]
	}
	return &clone
}

// Validate checks structural invariants and the internal checksum binding.
func (p *QRPayload) Validate() error {
	if p == nil {
		return ErrInvalidQRPayload
	}
	if p.ProtocolVersion != ProtocolVersion {
		return fmt.Errorf("%w: got %d, want %d", ErrUnsupportedProtocolVersion, p.ProtocolVersion, ProtocolVersion)
	}
	if len(p.Accounts) != 2 {
		return fmt.Errorf("%w: got %d accounts, want 2", ErrInvalidQRPayload, len(p.Accounts))
	}
	if p.Accounts[0].AccountID == "" || p.Accounts[1].AccountID == "" {
		return ErrInvalidAccountID
	}
	if p.Accounts[0].AccountID == p.Accounts[1].AccountID {
		return ErrDuplicateAccount
	}
	if !isZeroDigest(p.Accounts[0].AccountDigest) && !isZeroDigest(p.Accounts[1].AccountDigest) {
		expected := PairwiseChecksum(p.Accounts[0].AccountDigest, p.Accounts[1].AccountDigest)
		if subtle.ConstantTimeCompare(expected[:], p.Checksum[:]) != 1 {
			return ErrChecksumMismatch
		}
	}
	return nil
}

// Encode returns the compact JSON QR payload.
func (p *QRPayload) Encode() ([]byte, error) {
	if err := p.Validate(); err != nil {
		return nil, err
	}
	raw := qrPayloadJSON{
		ProtocolVersion: p.ProtocolVersion,
		Accounts:        make([]qrPartyJSON, len(p.Accounts)),
		Checksum:        hex.EncodeToString(p.Checksum[:]),
	}
	for i, account := range p.Accounts {
		raw.Accounts[i] = qrPartyJSON{
			AccountID:     account.AccountID,
			ListVersion:   account.ListVersion,
			ListDigest:    hex.EncodeToString(account.ListDigest[:]),
			AccountDigest: hex.EncodeToString(account.AccountDigest[:]),
		}
	}
	return json.Marshal(raw)
}

// EncodeQRPayload encodes a payload as compact JSON.
func EncodeQRPayload(payload *QRPayload) ([]byte, error) {
	return payload.Encode()
}

// MarshalJSON implements json.Marshaler.
func (p QRPayload) MarshalJSON() ([]byte, error) {
	encoded, err := p.Encode()
	if err != nil {
		return nil, err
	}
	return encoded, nil
}

// UnmarshalJSON implements json.Unmarshaler.
func (p *QRPayload) UnmarshalJSON(data []byte) error {
	decoded, err := DecodeQRPayload(data)
	if err != nil {
		return err
	}
	*p = *decoded
	return nil
}

// DecodeQRPayload parses a strict JSON QR payload.
func DecodeQRPayload(data []byte) (*QRPayload, error) {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()

	var raw qrPayloadJSON
	if err := decoder.Decode(&raw); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrInvalidQRPayload, err)
	}
	if err := ensureJSONEOF(decoder); err != nil {
		return nil, err
	}

	checksum, err := decodeDigest(raw.Checksum, "checksum")
	if err != nil {
		return nil, err
	}
	accounts := make([]QRParty, len(raw.Accounts))
	for i, account := range raw.Accounts {
		listDigest, err := decodeDigest(account.ListDigest, "list_digest")
		if err != nil {
			return nil, err
		}
		var accountDigest [32]byte
		if account.AccountDigest != "" {
			accountDigest, err = decodeDigest(account.AccountDigest, "account_digest")
			if err != nil {
				return nil, err
			}
		}
		accounts[i] = QRParty{
			AccountID:     account.AccountID,
			ListVersion:   account.ListVersion,
			ListDigest:    listDigest,
			AccountDigest: accountDigest,
		}
	}

	payload := &QRPayload{
		ProtocolVersion: raw.ProtocolVersion,
		Accounts:        accounts,
		Checksum:        checksum,
	}
	if err := payload.Validate(); err != nil {
		return nil, err
	}
	return payload, nil
}

// DecodeQRText is an alias for DecodeQRPayload.
func DecodeQRText(data []byte) (*QRPayload, error) {
	return DecodeQRPayload(data)
}

func decodeDigest(encoded, field string) ([32]byte, error) {
	var digest [32]byte
	if strings.TrimSpace(encoded) == "" {
		return digest, fmt.Errorf("%w: missing %s", ErrInvalidQRPayload, field)
	}
	decoded, err := hex.DecodeString(encoded)
	if err != nil {
		return digest, fmt.Errorf("%w: %s is not hex: %v", ErrInvalidQRPayload, field, err)
	}
	if len(decoded) != len(digest) {
		return digest, fmt.Errorf("%w: %s has %d bytes, want 32", ErrInvalidQRPayload, field, len(decoded))
	}
	copy(digest[:], decoded)
	return digest, nil
}

func ensureJSONEOF(decoder *json.Decoder) error {
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		if err == nil {
			return fmt.Errorf("%w: trailing JSON value", ErrInvalidQRPayload)
		}
		return fmt.Errorf("%w: %v", ErrInvalidQRPayload, err)
	}
	return nil
}
